<div class="policy-grid">
    <div><label class="prism-label" for="{{ $offense ? 'edit' : 'new' }}Code">Code <span class="text-danger">*</span></label><input class="prism-input" id="{{ $offense ? 'edit' : 'new' }}Code" name="code" maxlength="20" value="{{ old('code', $offense?->code) }}" placeholder="MINOR-16 or MAJOR-48" required></div>
    <div><label class="prism-label" for="{{ $offense ? 'edit' : 'new' }}Type">Type <span class="text-danger">*</span></label><select class="prism-select" id="{{ $offense ? 'edit' : 'new' }}Type" name="offense_type" required><option value="minor" @selected(old('offense_type', $offense?->offense_type) === 'minor')>Minor</option><option value="major" @selected(old('offense_type', $offense?->offense_type) === 'major')>Major</option></select></div>
    <div class="wide"><label class="prism-label" for="{{ $offense ? 'edit' : 'new' }}Title">Offense Title <span class="text-danger">*</span></label><input class="prism-input" id="{{ $offense ? 'edit' : 'new' }}Title" name="title" maxlength="255" value="{{ old('title', $offense?->title) }}" placeholder="e.g., Non-wearing of prescribed uniform" required></div>
    <div class="wide"><label class="prism-label" for="{{ $offense ? 'edit' : 'new' }}Description">Description <span class="text-danger">*</span></label><textarea class="prism-input" id="{{ $offense ? 'edit' : 'new' }}Description" name="description" required minlength="10" maxlength="5000" placeholder="Describe the offense and prohibited conduct.">{{ old('description', $offense?->description) }}</textarea></div>
    <div class="wide"><label class="prism-label" for="{{ $offense ? 'edit' : 'new' }}Keywords">Search Keywords <span class="policy-optional">(Optional)</span></label><textarea class="prism-input" id="{{ $offense ? 'edit' : 'new' }}Keywords" name="keywords" maxlength="2000" placeholder="Comma-separated terms">{{ old('keywords', implode(', ', $offense?->keywords ?? [])) }}</textarea><p class="policy-help">Keywords help match case descriptions to this offense; new codes need separate ML training for model suggestions.</p></div>
    <div><label class="prism-label" for="{{ $offense ? 'edit' : 'new' }}Section">Handbook Section <span class="policy-optional">(Optional)</span></label><input class="prism-input" id="{{ $offense ? 'edit' : 'new' }}Section" name="handbook_section" maxlength="50" value="{{ old('handbook_section', $offense?->handbook_section) }}" placeholder="e.g., Section VI.D"></div>
    <div><label class="prism-label" for="{{ $offense ? 'edit' : 'new' }}Page">Handbook Page <span class="policy-optional">(Optional)</span></label><input class="prism-input" id="{{ $offense ? 'edit' : 'new' }}Page" name="handbook_page" maxlength="10" value="{{ old('handbook_page', $offense?->handbook_page) }}" placeholder="e.g., 33"></div>
    <div class="wide"><label class="prism-label" for="{{ $offense ? 'edit' : 'new' }}Consequence">Special Consequence <span class="policy-optional">(Optional)</span></label><input class="prism-input" id="{{ $offense ? 'edit' : 'new' }}Consequence" name="special_consequence" maxlength="100" value="{{ old('special_consequence', $offense?->special_consequence) }}" placeholder="e.g., Referral to the disciplinary committee"></div>
    <div class="wide"><label class="prism-label" for="{{ $offense ? 'edit' : 'new' }}Reason">Reason and Policy Source <span class="text-danger">*</span></label><textarea class="prism-input" id="{{ $offense ? 'edit' : 'new' }}Reason" name="reason" required minlength="10" maxlength="1000" placeholder="Document the approved policy source or correction."></textarea></div>
</div>
